export type ParsedContributeFeesInstruction<
  TProgram extends string = typeof MUTAV_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** Signs the instruction and the BRS transfers from its own account. */
    operator: TAccountMetas[0];
    config: TAccountMetas[1];
    state: TAccountMetas[2];
    /**
     * The fee's `IncomeReceipt` (kind `FEE`): one per invoice, so a second
     * contribution of the same invoice fails here.
     */
    feeReceipt: TAccountMetas[3];
    /**
     * The operator's own BRS token account (fees reach it via PIX → BRS).
     * Must be owned by the operator: spending through a delegate is refused
     * (spec §5.3).
     */
    source: TAccountMetas[4];
    reserve: TAccountMetas[5];
    /** The whitelisted MUTAV treasury: receives the take directly. */
    treasuryAccount: TAccountMetas[6];
    reserveMint: TAccountMetas[7];
    tokenProgram: TAccountMetas[8];
    payer: TAccountMetas[9];
    systemProgram: TAccountMetas[10];
    eventAuthority: TAccountMetas[11];
    program: TAccountMetas[12];
  };
  data: ContributeFeesInstructionData;
};

export function parseContributeFeesInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedContributeFeesInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 13) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 13,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      operator: getNextAccount(),
      config: getNextAccount(),
      state: getNextAccount(),
      feeReceipt: getNextAccount(),
      source: getNextAccount(),
      reserve: getNextAccount(),
      treasuryAccount: getNextAccount(),
      reserveMint: getNextAccount(),
      tokenProgram: getNextAccount(),
      payer: getNextAccount(),
      systemProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getContributeFeesInstructionDataDecoder().decode(instruction.data),
  };
}
